function load<T>(key: string, fallback: T): T { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; } }
export function calculateSEPAScore(tradeData: SepaInput): SepaResult { const riskPct = tradeData.entryPrice ? Math.abs((tradeData.entryPrice - tradeData.stopLossPrice) / tradeData.entryPrice) * 100 : 0; const chasingPct = tradeData.pivotPrice ? ((tradeData.entryPrice - tradeData.pivotPrice) / tradeData.pivotPrice) * 100 : 0; const trend = (tradeData.aboveMa50Ma200 ? 10 : 0) + (tradeData.ma200Uptrend ? 10 : 0) + (tradeData.near52wHigh ? 10 : 0); const standardPattern = ["VCP", "CUP_HANDLE", "HTF"].includes(tradeData.patternType); const pattern = (standardPattern ? 15 : 0) + (tradeData.patternType === "VCP" && (tradeData.vcpContractions || 0) >= 2 ? 10 : 0) + (tradeData.patternType === "VCP" && (tradeData.lastContractionPct ?? 999) <= 8 ? 5 : 0); const chasePoints = tradeData.entryPrice > 0 && tradeData.pivotPrice > 0 ? (chasingPct <= 2 ? 15 : chasingPct <= 5 ? 5 : 0) : 0; const execution = (tradeData.volumeDryup ? 10 : 0) + chasePoints; const riskMarket = (tradeData.entryPrice > 0 && tradeData.stopLossPrice > 0 && riskPct <= 8 ? 10 : 0) + (tradeData.marketRegime === "CONFIRMED_UPTREND" ? 5 : 0); const score = Math.max(0, Math.min(100, trend + pattern + execution + riskMarket)); const grade = score >= 90 ? "A+" : score >= 75 ? "A" : score >= 60 ? "B" : "C / FOMO"; const chaseText = chasingPct <= 2 ? "Entry is close to pivot" : chasingPct <= 5 ? "Mild chasing above pivot" : "Heavy chasing above pivot"; const feedback = riskPct > 8 ? "Risk exceeds 8%; reduce position size or move the stop closer." : grade === "C / FOMO" ? "Setup needs more confirmation before execution." : grade === "A+" ? "Excellent alignment between trend, base, execution and risk." : `${chaseText}. Review the missing checklist items before entry.`; return { score, grade, riskPct, chasingPct, breakdown: [{ label: "Trend Template", points: trend, max: 30, detail: `${[tradeData.aboveMa50Ma200, tradeData.ma200Uptrend, tradeData.near52wHigh].filter(Boolean).length}/3 conditions` }, { label: "Base Pattern", points: pattern, max: 30, detail: tradeData.patternType }, { label: "Execution Quality", points: execution, max: 25, detail: `${chasePoints} chase points · ${tradeData.volumeDryup ? "dry-up confirmed" : "no dry-up"}` }, { label: "Risk & Market", points: riskMarket, max: 15, detail: `${riskPct.toFixed(2)}% risk · ${tradeData.marketRegime}` }], feedback }; }
function calc(form: TradeForm) { const scalarEntry = Number(form.entryPrice) || 0; const scalarExit = Number(form.exitPrice) || 0; const scalarSize = Number(form.positionSize) || 0; const stop = Number(form.stopLoss) || 0; const target = Number(form.takeProfit) || 0; const entries = (form.entryLegs || []).map(x => ({ price: Number(x.price) || 0, size: Number(x.size) || 0 })).filter(x => x.price > 0 && x.size > 0); const exits = (form.exitLegs || []).map(x => ({ price: Number(x.price) || 0, size: Number(x.size) || 0 })).filter(x => x.price > 0 && x.size > 0); const entrySize = entries.reduce((sum, x) => sum + x.size, 0) || scalarSize; const exitSize = exits.reduce((sum, x) => sum + x.size, 0) || scalarSize; const entry = entries.length ? entries.reduce((sum, x) => sum + x.price * x.size, 0) / entrySize : scalarEntry; const exit = exits.length ? exits.reduce((sum, x) => sum + x.price * x.size, 0) / exitSize : scalarExit; const size = Math.max(entrySize, exitSize); const grossPnl = form.direction === "Long" ? (exit - entry) * size : (entry - exit) * size; const slippageCost = Math.abs(Number(form.slippage) || 0) * size; const tradingFee = Number(form.tradingFee) || 0; const swapFee = Number(form.swapFee) || 0; const pnl = grossPnl - slippageCost - tradingFee - swapFee; const riskAmount = Math.abs(entry - stop) * size; const rMultiple = riskAmount ? pnl / riskAmount : 0; return { grossPnl, slippageCost, tradingFee, swapFee, pnl, riskAmount, rMultiple, rrRatio: Math.abs(target - entry) / Math.abs(entry - stop || 1), result: rMultiple > 0.05 ? "win" as Result : rMultiple < -0.05 ? "loss" as Result : "breakeven" as Result }; }
function toTrade(form: TradeForm, existing?: LocalTrade): LocalTrade { const c = calc(form); const sepa = calculateSEPAScore({ entryPrice: Number(form.entryPrice) || 0, stopLossPrice: Number(form.stopLoss) || 0, pivotPrice: Number((form as TradeForm & { pivotPrice?: string }).pivotPrice) || Number(form.entryPrice) || 0, aboveMa50Ma200: form.aboveMa50Ma200, ma200Uptrend: form.ma200Uptrend, near52wHigh: form.near52wHigh, patternType: form.patternType, vcpContractions: Number(form.vcpContractions) || 0, lastContractionPct: form.lastContractionPct === "" ? undefined : Number(form.lastContractionPct), volumeDryup: form.volumeDryup, marketRegime: form.marketRegime }); const complete = Boolean(form.symbol && ((form.entryLegs || []).some(x => x.price && x.size) || form.entryPrice) && ((form.exitLegs || []).some(x => x.price && x.size) || form.exitPrice) && (form.positionSize || (form.entryLegs || []).some(x => x.size)) && form.stopLoss && form.takeProfit); return { id: existing?.id ?? Date.now(), accountId: existing?.accountId || "main", pivotPrice: Number(form.pivotPrice) || Number(form.entryPrice) || 0, aboveMa50Ma200: form.aboveMa50Ma200, ma200Uptrend: form.ma200Uptrend, near52wHigh: form.near52wHigh, patternType: form.patternType, vcpContractions: Number(form.vcpContractions) || undefined, lastContractionPct: form.lastContractionPct === "" ? undefined : Number(form.lastContractionPct), volumeDryup: form.volumeDryup, marketRegime: form.marketRegime, sepaScore: sepa.score, sepaGrade: sepa.grade, chasingPct: sepa.chasingPct, sepaRiskPct: sepa.riskPct, symbol: form.symbol || "Untitled", assetType: form.assetType, direction: form.direction, setup: form.setup, entryPrice: Number(form.entryPrice) || 0, exitPrice: Number(form.exitPrice) || 0, positionSize: Number(form.positionSize) || 0, stopLoss: Number(form.stopLoss) || 0, takeProfit: Number(form.takeProfit) || 0, riskTradePct: Number(form.riskTradePct) || 1, tradingFee: c.tradingFee, swapFee: c.swapFee, grossPnl: complete ? c.grossPnl : 0, pnl: complete ? c.pnl : 0, riskAmount: complete ? c.riskAmount : 0, rrRatio: complete ? c.rrRatio : 0, rMultiple: complete ? c.rMultiple : 0, result: complete ? c.result : "breakeven", isComplete: complete, chartUrl: form.chartUrl, setupChartUrl: form.setupChartUrl, exitChartUrl: form.exitChartUrl, slippage: Number(form.slippage) || 0, entryLegs: (form.entryLegs || []).filter(x => Number(x.price) > 0 && Number(x.size) > 0).map(x => ({ price: Number(x.price), size: Number(x.size) })), exitLegs: (form.exitLegs || []).filter(x => Number(x.price) > 0 && Number(x.size) > 0).map(x => ({ price: Number(x.price), size: Number(x.size) })), notes: form.notes, openedAt: form.openedAt, closedAt: form.closedAt || form.openedAt } as LocalTrade; }
function mockTrades(): LocalTrade[] { const rows = [{ s: "NVDA", a: "Stocks" as AssetType, d: "Long" as Direction, setup: "VCP Breakout", p: 420, r: 2.1, date: "2026-09-18T13:00:00" }, { s: "BTCUSDT", a: "Crypto" as AssetType, d: "Long" as Direction, setup: "Trend Following", p: 285, r: 1.4, date: "2026-09-23T13:00:00" }, { s: "AAPL", a: "Stocks" as AssetType, d: "Short" as Direction, setup: "Pullback", p: -160, r: -0.8, date: "2026-09-29T13:00:00" }, { s: "CL1!", a: "Commodities/Futures" as AssetType, d: "Long" as Direction, setup: "Trend Following", p: 310, r: 1.7, date: "2026-10-03T13:00:00" }, { s: "MSFT", a: "Stocks" as AssetType, d: "Long" as Direction, setup: "CANSLIM", p: 95, r: .5, date: "2026-10-08T13:00:00" }, { s: "ETHUSDT", a: "Crypto" as AssetType, d: "Short" as Direction, setup: "Anti-Martingale", p: -75, r: -.4, date: "2026-10-10T13:00:00" }]; return rows.map((x, i) => { const fee = Math.abs(x.p) * .03; const net = x.p - fee; const risk = Math.abs(net / x.r); return { id: i + 1, accountId: i % 3 === 0 ? "crypto" : "main", symbol: x.s, assetType: x.a, direction: x.d, setup: x.setup, entryPrice: 100, exitPrice: 101, positionSize: 100, stopLoss: 99, takeProfit: 103, riskTradePct: 1, tradingFee: fee, swapFee: 0, grossPnl: x.p, pnl: net, riskAmount: risk, rrRatio: 2, rMultiple: net / risk, result: net > 0 ? "win" : "loss", isComplete: true, chartUrl: "", notes: "Local demo trade", openedAt: x.date, closedAt: x.date } as LocalTrade; }); }
